<template><section><h3>持久化数据卷</h3><p class="muted">仅支持已有命名卷。平台创建的卷位于数据盘；外部卷只允许只读挂载。</p><p v-if="error" class="notice warning">{{error}}</p><div v-for="(mount,index) in modelValue" :key="index" class="form-grid" style="margin-top:14px"><label>来源数据卷<select aria-label="来源数据卷" :value="mount.source" required @change="change(index,'source',$event.target.value)"><option value="" disabled>选择已存在的数据卷</option><option v-for="volume in data?.Volumes||[]" :key="volume.Name" :value="volume.Name">{{volume.Name}}</option></select></label><label>容器内目录<input :value="mount.target" required placeholder="/data" @input="change(index,'target',$event.target.value)"></label><label><input type="checkbox" :checked="mount.readOnly" @change="change(index,'readOnly',$event.target.checked)"> 只读挂载</label><button type="button" @click="remove(index)">移除此映射</button></div><button type="button" style="margin-top:12px" @click="add">＋ 添加数据卷映射</button></section></template>
<script setup>
import {watch} from 'vue';import {get,nodePath} from '../../api/client';import {useResource} from '../../composables/useResource';const props=defineProps({node:[String,Number],modelValue:{type:Array,default:()=>[]}}),emit=defineEmits(['update:modelValue']);const {data,error,refresh}=useResource(signal=>props.node?get(nodePath(props.node,'/manager/volumes'),signal):Promise.resolve({Volumes:[]}));watch(()=>props.node,refresh);function change(index,key,value){emit('update:modelValue',props.modelValue.map((item,i)=>i===index?{...item,[key]:value}:item));}function add(){emit('update:modelValue',[...props.modelValue,{source:'',target:'',readOnly:false}]);}function remove(index){emit('update:modelValue',props.modelValue.filter((_,i)=>i!==index));}
</script>
